-- 2) Precio por m² (SALE en USD, RENT en ARS/mes; 2 períodos, igual que V2).
WITH precios(name, sale_usd_m2, rent_ars_m2) AS (
    VALUES
        ('Agronomía', 2200, 11000),
        ('Chacarita', 2500, 12500),
        ('Coghlan', 2400, 11800),
        ('Constitución', 1500, 8500),
        ('Floresta', 1800, 9500),
        ('La Paternal', 2000, 10200),
        ('Liniers', 1600, 8800),
        ('Mataderos', 1500, 8200),
        ('Monte Castro', 1900, 9800),
        ('Nueva Pompeya', 1300, 7500),
        ('Parque Avellaneda', 1600, 8600),
        ('Parque Chacabuco', 1900, 9700),
        ('Parque Chas', 2100, 10500),
        ('Parque Patricios', 1700, 9000),
        ('Saavedra', 2300, 11500),
        ('San Cristóbal', 1700, 9200),
        ('Vélez Sarsfield', 1700, 9000),
        ('Versalles', 1700, 9000),
        ('Villa del Parque', 2200, 11200),
        ('Villa General Mitre', 2100, 10800),
        ('Villa Lugano', 1200, 7000),
        ('Villa Luro', 1700, 9000),
        ('Villa Ortúzar', 2200, 11000),
        ('Villa Pueyrredón', 2000, 10200),
        ('Villa Real', 1700, 9000),
        ('Villa Riachuelo', 1200, 7000),
        ('Villa Santa Rita', 1900, 9600),
        ('Villa Soldati', 1200, 7000)
)
INSERT INTO neighborhood_price_m2 (neighborhood_id, operation_type, avg_price_m2, period)
SELECT n.id, op.operation_type,
       ROUND((CASE WHEN op.operation_type = 'SALE' THEN p.sale_usd_m2 ELSE p.rent_ars_m2 END) * per.factor, 2),
       per.period
FROM precios p
JOIN neighborhood n ON n.name = p.name
CROSS JOIN (VALUES ('SALE'), ('RENT')) AS op(operation_type)
CROSS JOIN (VALUES (DATE '2026-05-01', 0.97), (DATE '2026-06-01', 1.00)) AS per(period, factor);

